'use client';

import React from 'react';
import { LicitacaoMatch, MatchStatus } from '../../lib/types';
import { CountdownTimer } from './CountdownTimer';
import { Building2, MapPin, Tag, ExternalLink, DollarSign, CheckCircle2, XCircle, Bookmark, Eye } from 'lucide-react';

interface LicitacaoCardProps {
  match: LicitacaoMatch;
  onAtualizarStatus: (id: string, novoStatus: MatchStatus) => void;
}

export function LicitacaoCard({ match, onAtualizarStatus }: LicitacaoCardProps) {
  const { licitacao, status, termosCorrespondentes } = match;

  const formatarMoeda = (valor?: number) => {
    if (!valor) return 'Valor não informado';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(valor);
  };

  return (
    <div className="bg-slate-900/90 border border-slate-800 rounded-xl p-5 hover:border-slate-700 transition-all flex flex-col justify-between space-y-4 shadow-sm">
      {/* Top Header: Badge Modalidade & Countdown Timer */}
      <div className="flex items-start justify-between gap-3">
        <div className="flex items-center gap-2 flex-wrap">
          <span className="px-2.5 py-1 rounded-md text-[11px] font-semibold bg-blue-500/10 text-blue-400 border border-blue-500/20">
            {licitacao.modalidadeNome}
          </span>
          <span className="px-2 py-0.5 rounded text-[11px] font-bold bg-slate-800 text-slate-300">
            {licitacao.uf}
          </span>
        </div>
        <CountdownTimer dataEncerramento={licitacao.dataEncerramentoProposta} />
      </div>

      {/* Title / Órgão & Objeto */}
      <div>
        <div className="flex items-center gap-1.5 text-slate-400 text-xs font-medium mb-1">
          <Building2 className="w-3.5 h-3.5 text-slate-500" />
          <span className="truncate">{licitacao.orgaoRazaoSocial}</span>
        </div>
        <h3 className="text-slate-100 text-sm font-semibold leading-snug line-clamp-3 mb-2">
          {licitacao.objetoCompra}
        </h3>
        <div className="flex items-center gap-1.5 text-slate-400 text-xs">
          <MapPin className="w-3.5 h-3.5 text-slate-500" />
          <span>{licitacao.municipio} - {licitacao.uf}</span>
        </div>
      </div>

      {/* Match Tags */}
      <div className="flex items-center gap-1.5 flex-wrap">
        <span className="text-[10px] text-slate-500 font-semibold uppercase flex items-center gap-1">
          <Tag className="w-3 h-3" /> Matches:
        </span>
        {termosCorrespondentes.map((termo, idx) => (
          <span
            key={idx}
            className="px-2 py-0.5 rounded bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 text-[11px] font-medium"
          >
            {termo}
          </span>
        ))}
      </div>

      {/* Valor Estimado & Enlace PNCP */}
      <div className="pt-3 border-t border-slate-800/80 flex items-center justify-between">
        <div>
          <p className="text-[10px] text-slate-500 font-semibold uppercase">Valor Estimado</p>
          <p className="text-sm font-bold text-slate-100 flex items-center gap-1">
            <DollarSign className="w-3.5 h-3.5 text-emerald-400" />
            {formatarMoeda(licitacao.valorTotalEstimado)}
          </p>
        </div>

        {licitacao.linkSistemaOrigem && (
          <a
            href={licitacao.linkSistemaOrigem}
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-blue-400 hover:text-blue-300 font-semibold flex items-center gap-1 hover:underline"
          >
            <span>Ver PNCP</span>
            <ExternalLink className="w-3.5 h-3.5" />
          </a>
        )}
      </div>

      {/* Botões de Ação para o Funil de Oportunidades */}
      <div className="pt-2 flex items-center gap-1.5 justify-end">
        {status !== 'EM_ANALISE' && (
          <button
            onClick={() => onAtualizarStatus(match.id, 'EM_ANALISE')}
            className="px-2.5 py-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 text-xs font-semibold flex items-center gap-1 transition-colors"
            title="Mover para Em Análise"
          >
            <Eye className="w-3.5 h-3.5 text-amber-400" />
            <span>Analisar</span>
          </button>
        )}

        {status !== 'SALVA' && (
          <button
            onClick={() => onAtualizarStatus(match.id, 'SALVA')}
            className="px-2.5 py-1.5 rounded-lg bg-emerald-600/20 hover:bg-emerald-600/30 text-emerald-400 text-xs font-semibold flex items-center gap-1 transition-colors border border-emerald-500/30"
            title="Salvar Oportunidade"
          >
            <Bookmark className="w-3.5 h-3.5 text-emerald-400" />
            <span>Salvar</span>
          </button>
        )}

        {status !== 'DESCARTADA' && (
          <button
            onClick={() => onAtualizarStatus(match.id, 'DESCARTADA')}
            className="px-2.5 py-1.5 rounded-lg bg-red-500/10 hover:bg-red-500/20 text-red-400 text-xs font-semibold flex items-center gap-1 transition-colors border border-red-500/20"
            title="Descartar Edital"
          >
            <XCircle className="w-3.5 h-3.5" />
            <span>Descartar</span>
          </button>
        )}
      </div>
    </div>
  );
}
